async function callGenerativeFallback(prompt, helpers, index = 0) {
  await new Promise(r => setTimeout(r, 2000 + (index * 2000))); // Dynamic stagger

  let lastError = null;

  for (let fb of fallbackWaterfall) {
    let fbEndpoint = '';
    let fbHeaders = { 'Content-Type': 'application/json' };
    let payload = {};

    if (fb.provider === 'google') {
      fbEndpoint = `https://generativelanguage.googleapis.com/v1beta/models/${fb.model}:generateContent?key=${geminiKey}`;
      payload = { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: "application/json" } };
    } else if (fb.provider === 'anthropic') {
      fbEndpoint = 'https://api.anthropic.com/v1/messages';
      fbHeaders['x-api-key'] = apiKey;
      fbHeaders['anthropic-version'] = '2023-06-01';
      payload = { model: fb.model, max_tokens: 1024, messages: [{ role: 'user', content: prompt }] };
      // Anthropic does not support response_format json_object natively in haiku without tools
    } else {
      fbHeaders['Authorization'] = `Bearer ${apiKey}`;
      if (fb.provider === 'groq') fbEndpoint = 'https://api.groq.com/openai/v1/chat/completions';
      else if (fb.provider === 'openrouter') fbEndpoint = 'https://openrouter.ai/api/v1/chat/completions';
      else fbEndpoint = 'https://api.openai.com/v1/chat/completions'; // OpenAI or default

      payload = { model: fb.model, messages: [{ role: 'user', content: prompt }], response_format: { type: "json_object" } };
    }

    try {
      const res = await helpers.httpRequest({ method: 'POST', url: fbEndpoint, headers: fbHeaders, body: payload, json: true });
      let text = '';
      if (fb.provider === 'google') text = res.candidates[0].content.parts[0].text;
      else if (fb.provider === 'anthropic') text = res.content[0].text;
      else text = res.choices[0].message.content;

      text = text.replace(/\r?\n|\r/g, '').replace(/\`\`\`json/g, '').replace(/\`\`\`/g, '').trim();
      // Ensure it's valid JSON
      let parsed = JSON.parse(text);
      return { parsed: parsed, usedModel: fb.model };
    } catch(e) {
      lastError = e.message;
      await new Promise(r => setTimeout(r, 2000)); // Delay before retry
    }
  }
  throw new Error(`All fallback models failed. Last error: ${lastError}`);
}

async function processJob(item, helpers) {
  const draft = item.json.humanized_cover_letter || item.json.draft || '';
  if (!draft) { item.json.needs_rewrite = false; return; }

  const state = `Draft Content to Evaluate:\n${draft}`;

  if (isJev) {
    const payload = {
      model: model,
      state: state,
      questions: {
        has_cliches: { type: "noul", instructions: "Does this text heavily rely on overused buzzwords like delve, seamless, robust, tapestry, elevate, or boast?" },
        has_fabrications: { type: "noul", instructions: "Does this text invent specific company names, metrics, or factual claims that seem fabricated as placeholders?" }
      }
    };
    try {
      const res = await helpers.httpRequest({ method: 'POST', url: endpoint, headers, body: payload, json: true });
      const ans = res.answers || res.choices[0]?.message?.tool_calls[0]?.function?.arguments || res;

      const cliches = ans.has_cliches?.noul || 0;
      const fabrications = ans.has_fabrications?.noul || 0;

      item.json.cliche_hits = Math.round(cliches * 10);
      item.json.needs_rewrite = cliches > 0.6 || fabrications > 0.5;
      return;
    } catch(e) {
      item.json.jev_error = e.message;
    }
  }

  try {
    const prompt = `Evaluate this cover letter draft.\n\n${state}\n\nRespond ONLY with a JSON object:\n{"has_cliches": boolean, "has_fabrications": boolean}`;
    const fbRes = await callGenerativeFallback(prompt, helpers, item.json.__index || 0);
    const parsed = fbRes.parsed;
    item.json.cliche_hits = parsed.has_cliches ? 5 : 0;
    item.json.needs_rewrite = parsed.has_cliches === true || parsed.has_fabrications === true;
  } catch(e) {
    item.json.needs_rewrite = false; 
    item.json.gemini_error = e.message;
  }
}

