function parseJobInput(text) {
  const urlMatch = text.match(/https?:\/\/[^\s]+/i);
  const jobUrl = urlMatch ? urlMatch[0] : '';
  const cleaned = text.replace(/^\/[a-zA-Z0-9_\-]+\s*/i, '').trim();
  const lines = cleaned.split('\n').map(l => l.trim()).filter(Boolean);

  let title = '';
  let company = '';
  let description = cleaned;

  const roleMatch = cleaned.match(/(?:role|title|position):\s*([^\n\r]+)/i);
  const compMatch = cleaned.match(/(?:company|organization|employer):\s*([^\n\r]+)/i);

  if (roleMatch) title = roleMatch[1].trim();
  if (compMatch) company = compMatch[1].trim();

  if (!title && lines.length > 0) {
    const firstLine = lines[0];
    if (firstLine.includes(' at ')) {
      const parts = firstLine.split(/\s+at\s+/i);
      title = parts[0].trim();
      company = parts.slice(1).join(' at ').replace(/[-–,].*$/, '').trim();
    } else if (firstLine.includes(' - ')) {
      const parts = firstLine.split(/\s+-\s+/);
      title = parts[0].trim();
      if (parts[1] && parts[1].length < 50) company = parts[1].trim();
    } else {
      title = firstLine.slice(0, 70).trim();
      if (lines.length > 1 && lines[1].length < 50 && !lines[1].toLowerCase().startsWith('http') && !lines[1].toLowerCase().startsWith('about')) {
        company = lines[1].replace(/[-–,].*$/, '').trim();
      }
    }
  }

  if (!title) {
    title = (masterProfile.target_titles && masterProfile.target_titles[0]) || 'Target Role';
  }
  if (!company) {
    company = 'Hiring Company';
  }

  return { title, company, description, jobUrl };
}

