function escapeHtml(str) {
  if (!str || typeof str !== 'string') return '';
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function formatLocationName(loc) {
  if (geoHelper) return geoHelper.formatLocationName(loc);
  if (!loc || typeof loc !== 'string') return '';
  return loc.split(',').map(part => {
    const trimmed = part.trim();
    if (/^[A-Za-z]{2,4}$/.test(trimmed)) return trimmed.toUpperCase();
    return trimmed.replace(/\b\w+/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
  }).join(', ');
}

function parseSmartLocations(inputStr) {
  if (geoHelper) return geoHelper.parseSmartLocations(inputStr);
  if (!inputStr || typeof inputStr !== 'string') return [];
  return inputStr.split(/[;,|\r\n]+/).map(s => formatLocationName(s.trim())).filter(Boolean);
}

function harmonizeLocationAndWorkType(locations, workType, fallbackDetectedCity = null) {
  let finalLocs = Array.isArray(locations) ? [...locations] : (locations ? [locations] : []);
  if (finalLocs.length === 0 && fallbackDetectedCity) {
    finalLocs.push(fallbackDetectedCity);
  }

  const lowerWork = (workType || 'Open to All').toLowerCase();
  const isRemoteOnly = lowerWork.includes('remote only') || lowerWork === 'remote';
  const isHybrid = lowerWork.includes('hybrid');
  const isOnsite = lowerWork.includes('onsite');

  const hasRemoteInLoc = finalLocs.some(l => l.toLowerCase().includes('remote'));
  const hasPhysicalCity = finalLocs.some(l => !l.toLowerCase().includes('remote') && l.length > 1);
  let note = '';

  if (isRemoteOnly) {
    if (!hasRemoteInLoc) finalLocs.push('Remote');
    note = '🌐 Configured for 100% remote job matching.';
  } else if ((isHybrid || isOnsite) && !hasPhysicalCity && fallbackDetectedCity) {
    finalLocs.unshift(fallbackDetectedCity);
    note = `💡 Paired with ${fallbackDetectedCity} from your profile for local searches.`;
  }

  return {
    locations: [...new Set(finalLocs.filter(Boolean))],
    work_type: workType || 'Open to All (Remote, Hybrid, Onsite)',
    harmonizationNote: note
  };
}

