    if (cancelCommands.includes(firstWord)) {
      setTelegramState(chatId, null);
      if (chatId && botToken) {
        const cancelText = (prevState && prevState.action)
          ? `✅ <b>Action Cancelled:</b> Aborted pending <code>/${prevState.action.toLowerCase()}</code>. You're ready for any new command!`
          : `✅ <b>Action Cancelled.</b> You have a clean slate! Send <code>/help</code> to see options.`;

