    }

    // Switch notice to give clear feedback when replacing a previous pending action
    const abortNotice = (prevState && prevState.action && isCommand && !firstWord.includes(prevState.action.toLowerCase()) && !['/help', '/start', '/status', '/stats', '/applied'].includes(firstWord))
      ? `🔄 <i>(Aborted previous /${prevState.action.toLowerCase()} action)</i>\n\n`
      : '';

