    // 2a3. THRESHOLD SETTING COMMAND (/threshold, /score-threshold, /min-score)
    if (firstWord === '/threshold' || firstWord === '/score-threshold' || firstWord === '/min-score') {
      const numArg = parseFloat(rest.trim());
      if (rest.trim() && !isNaN(numArg) && numArg >= 10 && numArg <= 100) {
        const updated = settingsHelper ? settingsHelper.updateSettings({ score_threshold: Math.round(numArg) }) : { score_threshold: numArg };
        if (chatId && botToken) {
          await this.helpers.httpRequest({
