            json: true
          });
        }
      }
      continue;
    }

    // 2a4. SCHEDULE SETTING COMMAND (/schedule, /cron, /frequency)
    if (firstWord === '/schedule' || firstWord === '/cron' || firstWord === '/frequency') {
      const parsedSched = settingsHelper ? settingsHelper.parseHumanSchedule(rest.trim()) : null;
      if (parsedSched) {
        const updated = settingsHelper ? settingsHelper.updateSettings({ cron_schedule: parsedSched.cron, cron_description: parsedSched.desc }) : {};
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `⏰ <b>Automation Schedule Updated!</b>\n\n` +
                `• <b>Frequency:</b> <b>${updated.cron_description || parsedSched.desc}</b>\n` +
                `• <b>Cron Expression:</b> <code>${updated.cron_schedule || parsedSched.cron}</code>\n\n` +
                `<i>Saved to <code>data/config/settings.json</code>.</i>`
            },
            json: true
          });
