    // 2a5. WORK TYPE SETTING COMMAND (/worktype, /workplace, /mode)
    if (firstWord === '/worktype' || firstWord === '/workplace' || firstWord === '/mode') {
      const arg = rest.trim().toLowerCase();
      let modeStr = '';
      if (arg.includes('remote')) modeStr = 'Remote Only';
      else if (arg.includes('hybrid')) modeStr = 'Hybrid & Remote';
      else if (arg.includes('onsite') || arg.includes('on-site')) modeStr = 'Onsite / Any';
      else if (arg.includes('all') || arg.includes('open') || arg.includes('any')) modeStr = 'Open to All';

      if (modeStr) {
        if (settingsHelper) settingsHelper.updateSettings({ work_type: modeStr });
        if (masterProfile) {
          masterProfile.work_type = modeStr;
          const dataDir = fs.existsSync('/data') ? '/data' : 'data';
          try { fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.json'), JSON.stringify(masterProfile, null, 2), 'utf8'); } catch(e) {}
        }
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `🏢 <b>Workplace Preference Updated!</b>\n\n` +
                `• <b>Mode:</b> <b>${modeStr}</b>\n\n` +
                `<i>Saved to <code>data/config/settings.json</code> and candidate profile.</i>`
