            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `🏢 <b>Current Workplace Mode:</b> <b>${cur}</b>\n\n` +
                `To change, send:\n` +
                `👉 <code>/worktype &lt;remote | hybrid | onsite | all&gt;</code>\n\n` +
                `<i>Examples: <code>/worktype remote</code> or <code>/worktype hybrid</code></i>`
            },
            json: true
          });
        }
      }
      continue;
    }

    // 2a6. TARGET ROLES SETTING COMMAND (/roles, /target-roles, /titles)
    if (firstWord === '/roles' || firstWord === '/target-roles' || firstWord === '/titles') {
      const rawTitles = rest.split(/[;,|\r\n]+/).map(s => s.trim()).filter(Boolean);
      if (rawTitles.length > 0) {
        masterProfile.target_titles = rawTitles;
        const dataDir = fs.existsSync('/data') ? '/data' : 'data';
        try {
          fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.json'), JSON.stringify(masterProfile, null, 2), 'utf8');
          fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.backup.json'), JSON.stringify(masterProfile, null, 2), 'utf8');
        } catch(e) {}

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `🎯 <b>Target Roles Updated!</b>\n\n` +
                `• <b>Active Roles:</b> <code>${rawTitles.join('; ')}</code>\n\n` +
                `<i>Saved to candidate profile. Future searches will dynamically evaluate these titles.</i>`
            },
            json: true
          });
        }
      } else {
        const cur = (masterProfile.target_titles || []).join('; ');
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `🎯 <b>Current Target Roles:</b>\n<code>${cur}</code>\n\n` +
                `To update, send:\n` +
                `👉 <code>/roles &lt;Title 1; Title 2; Title 3&gt;</code>\n\n` +
                `<i>Example: <code>/roles Data Analyst; Business Intelligence Analyst; Senior Data Analyst</code></i>`
            },
            json: true
          });
        }
      }
      continue;
    }

    // 2a7. TARGET LOCATIONS SETTING COMMAND (/locations, /target-locations, /cities)
    if (firstWord === '/locations' || firstWord === '/target-locations' || firstWord === '/cities') {
      const rawLocs = parseSmartLocations(rest);
      if (rawLocs.length > 0) {
        masterProfile.locations = rawLocs;
        const dataDir = fs.existsSync('/data') ? '/data' : 'data';
        try {
          fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.json'), JSON.stringify(masterProfile, null, 2), 'utf8');
          fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.backup.json'), JSON.stringify(masterProfile, null, 2), 'utf8');
        } catch(e) {}

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `📍 <b>Target Locations Updated!</b>\n\n` +
                `• <b>Active Locations:</b> <code>${rawLocs.join(', ')}</code>\n\n` +
                `<i>Saved to candidate profile.</i>`
            },
            json: true
          });
        }
      } else {
        const cur = (masterProfile.locations || []).join(', ');
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `📍 <b>Current Target Locations:</b>\n<code>${cur}</code>\n\n` +
                `To update, send:\n` +
                `👉 <code>/locations &lt;City 1; City 2; Remote&gt;</code>\n\n` +
                `<i>Example: <code>/locations Toronto, ON; Remote</code></i>`
            },
            json: true
          });
        }
      }
      continue;
    }

    // 2a8. BOARDS MANAGEMENT COMMAND (/boards, /job-boards)
    if (firstWord === '/boards' || firstWord === '/job-boards') {
      const parts = rest.trim().split(/\s+/);
      const boardName = parts[0]?.toLowerCase();
      const toggleVal = parts[1]?.toLowerCase();

      const validKeys = {
        'linkedin': 'linkedin',
        'indeed': 'indeed',
        'jobbank': 'canada_job_bank',
        'canada_job_bank': 'canada_job_bank',
        'adzuna': 'adzuna',
        'jobicy': 'jobicy',
        'remotive': 'remotive',
        'usajobs': 'usajobs'
      };

      if (boardName && validKeys[boardName] && (toggleVal === 'on' || toggleVal === 'off' || toggleVal === 'true' || toggleVal === 'false')) {
        const k = validKeys[boardName];
        const isEnable = (toggleVal === 'on' || toggleVal === 'true');
        const cur = settingsHelper ? settingsHelper.getSettings() : {};
        const newBoards = { ...(cur.boards_enabled || {}), [k]: isEnable };
        const updated = settingsHelper ? settingsHelper.updateSettings({ boards_enabled: newBoards }) : {};

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `📋 <b>Job Board ${boardName.toUpperCase()} is now ${isEnable ? '✅ ON' : '❌ OFF'}</b>\n\n` +
                `<i>Saved to <code>data/config/settings.json</code>.</i>`
            },
            json: true
          });
        }
      } else {
        const cur = settingsHelper ? settingsHelper.getSettings() : {};
        const b = cur.boards_enabled || {};
        const boardList = [
          `• LinkedIn: <b>${b.linkedin ? '✅ ON' : '❌ OFF'}</b>`,
          `• Indeed: <b>${b.indeed ? '✅ ON' : '❌ OFF'}</b>`,
          `• Canada Job Bank: <b>${b.canada_job_bank ? '✅ ON' : '❌ OFF'}</b>`,
          `• Adzuna: <b>${b.adzuna ? '✅ ON' : '❌ OFF'}</b>`,
          `• Jobicy Remote: <b>${b.jobicy ? '✅ ON' : '❌ OFF'}</b>`,
          `• Remotive Remote: <b>${b.remotive ? '✅ ON' : '❌ OFF'}</b>`,
          `• USAJOBS (Federal): <b>${b.usajobs ? '✅ ON' : '❌ OFF'}</b>`
        ].join('\n');

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `📋 <b>Job Board Ingestion Status:</b>\n\n${boardList}\n\n` +
                `To toggle a board via chat, send:\n` +
                `👉 <code>/boards &lt;board_name&gt; &lt;on|off&gt;</code>\n\n` +
                `<i>Or use interactive buttons in <code>/settings</code>.</i>`
            },
            json: true
          });
        }
      }
      continue;
    }

    // 2b. STATUS COMMAND (/status or /stats)
    if (firstWord === '/status' || firstWord === '/stats') {
      const seenCount = (jobsDb && typeof jobsDb.getSeenJobsCount === 'function') ? jobsDb.getSeenJobsCount() : 0;
      const pendingCount = (jobsDb && typeof jobsDb.getPendingJobs === 'function') ? jobsDb.getPendingJobs(1000).length : 0;
      const appliedCount = (jobsDb && typeof jobsDb.getAppliedJobs === 'function') ? jobsDb.getAppliedJobs(1000).length : 0;
      const rejectedCount = (jobsDb && typeof jobsDb.getRejectedJobs === 'function') ? jobsDb.getRejectedJobs(1000).length : 0;
      if (chatId && botToken) {
        await this.helpers.httpRequest({
          method: 'POST',
          url: `https://api.telegram.org/bot${botToken}/sendMessage`,
          body: {
            chat_id: chatId,
