            text: `📊 <b>Job Automation System Status</b>\n\n` +
              `🔍 <b>Total Jobs Ingested:</b> ${seenCount}\n` +
              `⏳ <b>Pending Review:</b> ${pendingCount}\n` +
              `✅ <b>Applications Delivered:</b> ${appliedCount}\n` +
              `❌ <b>Jobs Rejected:</b> ${rejectedCount}\n\n` +
              `👤 <b>Candidate:</b> ${masterProfile.name || 'Candidate'}\n` +
              `🎯 <b>Target Roles:</b> ${(masterProfile.target_titles || []).join(', ')}\n` +
              `📍 <b>Target Locations:</b> ${(masterProfile.locations || []).join(', ')}`
          },
          json: true
        });
      }
      continue;
    }

    // 2b2. FIND JOBS ON-DEMAND TRIGGER (/find-jobs, /fetch, /fetch-jobs, /scan, /search-jobs)
    if (firstWord === '/find-jobs' || firstWord === '/fetch' || firstWord === '/fetch-jobs' || firstWord === '/scan' || firstWord === '/search-jobs') {
      const dataDir = fs.existsSync('/data') ? '/data' : 'data';
      let currentProf = masterProfile;
      try {
        currentProf = JSON.parse(fs.readFileSync(path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.json'), 'utf8'));
      } catch(e) {}

      const roles = (currentProf.target_titles && currentProf.target_titles.length > 0) ? currentProf.target_titles : ['Target Role'];
      const locs = (currentProf.locations && currentProf.locations.length > 0) ? currentProf.locations : ['Remote'];

      if (chatId && botToken) {
        await this.helpers.httpRequest({
          method: 'POST',
          url: `https://api.telegram.org/bot${botToken}/sendMessage`,
          body: {
            chat_id: chatId,
            parse_mode: 'HTML',
            text: `🔍 <b>Job Ingestion Scan Triggered!</b>\n\n` +
              `📡 <b>Scanning Multi-Job Boards:</b>\n` +
              `• Adzuna API\n` +
              `• Canada Job Bank\n` +
              `• USAJOBS (Federal)\n` +
              `• Remotive & Jobicy Feeds\n` +
              `• LinkedIn & Indeed (Apify)\n\n` +
              `🎯 <b>Target Roles:</b> ${roles.slice(0, 4).join(', ')}\n` +
              `📍 <b>Target Locations:</b> ${locs.join(', ')}\n\n` +
              `⏱️ <b>Estimated Scan Time:</b> ~60–90 seconds\n\n` +
              `<i>Scanning, deduplicating, and scoring matches with Gemini AI. Qualifying matches (Score ≥ 70) with direct job links will arrive below!</i>`
          },
          json: true
        });

        try {
          const cp = require('child_process');
          const scriptPath = fs.existsSync('/scripts/run-pipeline.js')
            ? '/scripts/run-pipeline.js'
            : (fs.existsSync('scripts/run-pipeline.js') ? 'scripts/run-pipeline.js' : path.join(__dirname, 'run-pipeline.js'));

          const logFile = path.join(dataDir, 'pipeline_latest.log');
          const out = fs.openSync(logFile, 'a');

          const envObj = Object.assign(
            {},
            typeof process !== 'undefined' && process.env ? process.env : {},
            typeof $env !== 'undefined' ? $env : {},
            { DATA_DIR: dataDir }
          );

          const child = cp.spawn((typeof process !== 'undefined' && process.execPath) || 'node', [scriptPath, String(chatId)], {
            detached: true,
            stdio: ['ignore', out, out],
            env: envObj
          });
          child.unref();
          try { fs.closeSync(out); } catch(e) {}
          console.log('[Pipeline Trigger] Spawned pipeline scan PID:', child.pid);
        } catch(err) {
          console.error('Error triggering on-demand pipeline:', err.message);
        }
      }
      continue;
    }

    // 2c. APPLIED JOBS EXCEL EXPORT (/applied-joblist, /applied, /jobs-applied)
    if (firstWord === '/applied-joblist' || firstWord === '/applied_joblist' || firstWord === '/applied-jobs' || firstWord === '/applied' || firstWord === '/export-jobs') {
      if (chatId && botToken) {
        try {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
