            },
            json: true
          });
        } catch(err) {}

        try {
          const cp = require('child_process');
          const scriptPath = fs.existsSync('/scripts/export-applied-jobs.js')
            ? '/scripts/export-applied-jobs.js'
            : 'scripts/export-applied-jobs.js';

          cp.execFileSync('node', [scriptPath, String(chatId)], {
            timeout: 25000,
            encoding: 'utf8'
          });
        } catch(err) {
          console.error('Error exporting applied jobs to Excel:', err.message);
        }
      }
      continue;
    }

    // 2c2. FRESHNESS FILTER SETTING (/freshness-filter, /freshness)
    if (firstWord === '/freshness-filter' || firstWord === '/freshness_filter' || firstWord === '/freshness') {
      const dataDir = fs.existsSync('/data') ? '/data' : 'data';
      const settingsPath = path.join(__dirname, '..', '..', 'data', 'config', 'settings.json');
      let currentSettings = { freshness_hours: 24 };
      try {
        if (fs.existsSync(settingsPath)) currentSettings = JSON.parse(fs.readFileSync(settingsPath, 'utf8'));
      } catch(e) {}

      const rawArg = rest.trim();
      const numArg = parseFloat(rawArg);

      if (rawArg && !isNaN(numArg) && numArg >= 1 && numArg <= 168) {
        currentSettings.freshness_hours = Math.round(numArg);
        try {
          fs.writeFileSync(settingsPath, JSON.stringify(currentSettings, null, 2), 'utf8');
        } catch(e) {}

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `⏱️ <b>Job Freshness Filter Updated!</b>\n\n` +
                `• <b>New Window:</b> <b>${currentSettings.freshness_hours} hours</b> (${(currentSettings.freshness_hours / 24).toFixed(1)} days)\n` +
                `• <b>Policy:</b> Ingestion boards will accept jobs posted within the last ${currentSettings.freshness_hours} hours.\n\n` +
                `<i>Saved to <code>data/config/settings.json</code>.</i>`
            },
            json: true
          });
        }
        continue;
      } else if (rawArg) {
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `⚠️ <b>Invalid Freshness Window:</b> "${rawArg}"\n\n` +
                `Please specify a duration in hours between <b>1 and 168</b> (up to 7 days).\n\n` +
                `<i>Example: <code>/freshness-filter 24</code> or <code>/freshness-filter 48</code></i>`
            },
            json: true
          });
        }
        continue;
      } else {
        const hours = currentSettings.freshness_hours || 24;
