                `• <code>/freshness-filter 72</code> (Last 3 days)`
            },
            json: true
          });
        }
        continue;
      }
    }

    // 2c3. IMPORT RESUME TO MASTER PROFILE (/import-resume, /import_resume, /resume-import)
    if (firstWord === '/import-resume' || firstWord === '/import_resume' || firstWord === '/resume-import') {
      const customPath = rest.length > 3 && (rest.endsWith('.pdf') || rest.endsWith('.txt') || rest.endsWith('.docx')) ? rest : '';

      if (customPath) {
        // Direct path provided (e.g. from internal bridge trigger)
        if (chatId && botToken) {
          try {
            const cp = require('child_process');
            const scriptPath = fs.existsSync('/scripts/import-resume-telegram.js')
              ? '/scripts/import-resume-telegram.js'
              : 'scripts/import-resume-telegram.js';

