            const cmdEnv = {
              ...(typeof process !== 'undefined' && process.env ? process.env : {}),
              GEMINI_API_KEY: $env.GEMINI_API_KEY || '',
              TELEGRAM_BOT_TOKEN: $env.TELEGRAM_BOT_TOKEN || '',
              TELEGRAM_CHAT_ID: $env.TELEGRAM_CHAT_ID || '',
              DATA_DIR: '/data'
