      continue;
    }

    // 2c4. VIEW & COPY PROFILE (/profile, /myprofile, /view-profile, /get-profile)
    if (firstWord === '/profile' || firstWord === '/myprofile' || firstWord === '/view-profile' || firstWord === '/get-profile') {
      const dataDir = fs.existsSync('/data') ? '/data' : 'data';
