      }

      const formattedJson = JSON.stringify(currentProf, null, 2);
      const totalBullets = (currentProf.experience || []).reduce((acc, exp) => acc + (exp.bullets ? exp.bullets.length : 0), 0);
      const email = (currentProf.contact && currentProf.contact.email) || currentProf.email || 'N/A';
      const phone = (currentProf.contact && currentProf.contact.phone) || currentProf.phone || 'N/A';

      const summaryText = `👤 <b>MASTER PROFILE — ${escapeHtml(currentProf.name)}</b>\n\n` +
        `📧 <b>Email:</b> ${escapeHtml(email)}\n` +
        `📞 <b>Phone:</b> ${escapeHtml(phone)}\n` +
        `📍 <b>Target Locations:</b> ${escapeHtml((currentProf.locations || []).join(', '))}\n` +
        `🏢 <b>Workplace Mode:</b> ${escapeHtml(currentProf.work_type || 'Open to All')}\n` +
        `🎯 <b>Target Roles:</b> ${escapeHtml((currentProf.target_titles || []).join(', '))}\n` +
        `💼 <b>Experience:</b> ${(currentProf.experience || []).length} positions (${totalBullets} achievements)\n` +
        `🛠️ <b>Skills:</b> ${(currentProf.skills || []).length} indexed skills\n\n` +
        `📁 <b>Attached file:</b> <code>master-profile.json</code> delivered below!\n` +
        `💡 <i>Download & edit the file, then send it back here to update your profile (or type <code>/update-profile</code> to paste JSON).</i>`;

      if (chatId && botToken) {
        // 1. Send clean summary card
        await this.helpers.httpRequest({
          method: 'POST',
          url: `https://api.telegram.org/bot${botToken}/sendMessage`,
          body: {
            chat_id: chatId,
            parse_mode: 'HTML',
            text: summaryText
          },
          json: true
        });

        // 2. Directly send master-profile.json as document file
        try {
          const cp = require('child_process');
          const scriptPath = fs.existsSync('/scripts/send-telegram-doc.js')
            ? '/scripts/send-telegram-doc.js'
            : 'scripts/send-telegram-doc.js';

          cp.execFileSync('node', [
            scriptPath,
            botToken,
            String(chatId),
            profilePath,
            'master-profile.json',
            '📄 <b>Master Profile JSON</b>\n💡 <i>Edit this file and upload it back here anytime to update!</i>'
          ], {
            timeout: 25000,
            encoding: 'utf8'
          });
        } catch(err) {
          console.error('Error sending master-profile.json as document:', err.message);
        }
      }
      continue;
    }

    // 2c5. UPDATE PROFILE COMMAND (/update-profile, /edit-profile)
    if (firstWord === '/update-profile' || firstWord === '/edit-profile') {
      const inlineJson = rest.trim();

      const applyProfileUpdate = async (inputJsonStr) => {
        let valResult = null;
        if (profileValidator && typeof profileValidator.validateProfileJson === 'function') {
          valResult = profileValidator.validateProfileJson(inputJsonStr);
        } else {
          try {
            const clean = inputJsonStr.replace(/^\x60{3}(?:json)?\s*/i, '').replace(/\s*\x60{3}$/i, '').trim();
            const parsed = JSON.parse(clean);
            const errs = [];
            if (!parsed.name) errs.push('Missing required field "name"');
            if (!parsed.skills || !Array.isArray(parsed.skills)) errs.push('Missing required field "skills" array');
            if (!parsed.experience || !Array.isArray(parsed.experience)) errs.push('Missing required field "experience" array');
            if (errs.length > 0) valResult = { valid: false, errors: errs };
            else valResult = { valid: true, profile: parsed };
          } catch(e) {
            valResult = { valid: false, errors: ['JSON Syntax Error: ' + e.message] };
          }
        }

        if (!valResult.valid) {
          const errList = (valResult.errors || ['Unknown validation error']).map(e => `• <code>${escapeHtml(e)}</code>`).join('\n');
          if (chatId && botToken) {
            await this.helpers.httpRequest({
              method: 'POST',
              url: `https://api.telegram.org/bot${botToken}/sendMessage`,
              body: {
                chat_id: chatId,
                parse_mode: 'HTML',
                text: `❌ <b>Profile Validation Failed</b>\n\n` +
                  `<b>Issues Detected:</b>\n${errList}\n\n` +
                  `<b>Required Fields Checklist:</b>\n` +
                  `• <code>name</code> (String, e.g. "Full Name")\n` +
                  `• <code>contact.email</code> (Valid email address)\n` +
                  `• <code>target_titles</code> or <code>role</code> (Array or string)\n` +
                  `• <code>locations</code> or <code>location</code> (Array or string)\n` +
                  `• <code>skills</code> (Non-empty array of strings)\n` +
                  `• <code>experience</code> (Array of objects with <code>role</code>, <code>company</code>, <code>dates</code>, <code>bullets</code>)\n\n` +
                  `<i>💡 Fix the errors above and re-paste your JSON, or send <code>/cancel</code> to abort.</i>`
              },
              json: true
            });
          }
          return false;
        }

        const dataDir = fs.existsSync('/data') ? '/data' : 'data';
        const targetPath = path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.json');
        const backupPath = path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.backup.json');

        try {
          if (fs.existsSync(targetPath)) {
            fs.copyFileSync(targetPath, backupPath);
          }
          fs.writeFileSync(targetPath, JSON.stringify(valResult.profile, null, 2), 'utf8');
        } catch(err) {
          console.error('Failed to write master-profile.json:', err.message);
        }

        setTelegramState(chatId, null);

        const totalBullets = (valResult.profile.experience || []).reduce((acc, exp) => acc + (exp.bullets ? exp.bullets.length : 0), 0);
        const email = (valResult.profile.contact && valResult.profile.contact.email) || 'N/A';

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `✅ <b>MASTER PROFILE SUCCESSFULLY UPDATED!</b>\n\n` +
                `👤 <b>Name:</b> ${escapeHtml(valResult.profile.name)}\n` +
                `📧 <b>Email:</b> ${escapeHtml(email)}\n` +
                `🎯 <b>Target Roles:</b> ${escapeHtml((valResult.profile.target_titles || []).join(', '))}\n` +
                `📍 <b>Locations:</b> ${escapeHtml((valResult.profile.locations || []).join(', '))}\n` +
                `🏢 <b>Workplace Mode:</b> ${escapeHtml(valResult.profile.work_type || 'Open to All')}\n` +
                `💼 <b>Experience:</b> ${(valResult.profile.experience || []).length} positions (${totalBullets} achievements)\n` +
                `🛠️ <b>Skills:</b> ${(valResult.profile.skills || []).length} indexed skills\n\n` +
                `💾 <i>Saved to <code>data/profiles/master-profile.json</code> (previous version backed up to <code>data/profiles/master-profile.backup.json</code>).</i>\n\n` +
                `🚀 <b>Ready for Action!</b> Try:\n` +
                `• <code>/profile</code> — View updated profile\n` +
                `• <code>/apply</code> — Generate tailored application package`
            },
            json: true
          });
        }
        return true;
      };

      if (inlineJson && (inlineJson.startsWith('{') || inlineJson.startsWith('```') || inlineJson.startsWith('`'))) {
        await applyProfileUpdate(inlineJson);
        continue;
      }

      setTelegramState(chatId, { action: 'AWAIT_PROFILE_JSON' });
      if (chatId && botToken) {
        await this.helpers.httpRequest({
          method: 'POST',
          url: `https://api.telegram.org/bot${botToken}/sendMessage`,
          body: {
            chat_id: chatId,
            parse_mode: 'HTML',
            text: abortNotice + `📝 <b>Action Selected: Update Master Profile (/update-profile)</b>\n\n` +
              `Please paste your edited JSON object in your next message.\n\n` +
              `💡 <i>Tip: Send <code>/profile</code> first if you need to copy your current profile JSON.</i>\n\n` +
              `<b>Required JSON Fields:</b>\n` +
              `• <code>name</code>\n` +
              `• <code>contact.email</code>\n` +
              `• <code>target_titles</code> (or <code>role</code>)\n` +
              `• <code>locations</code>\n` +
              `• <code>skills</code> (array)\n` +
              `• <code>experience</code> (array with <code>role</code>, <code>company</code>, <code>dates</code>, <code>bullets</code>)\n\n` +
              `<i>(Send <code>/cancel</code> anytime to abort)</i>`
          },
          json: true
        });
      }
      continue;
    }

    // Determine target action:
    let commandAction = '';
    let jdText = '';

    if (firstWord === '/score' || firstWord === '/match' || firstWord === '/eval') {
      if (!rest || (rest.length < 15 && !rest.includes('http://') && !rest.includes('https://'))) {
        setTelegramState(chatId, { action: 'SCORE' });
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: abortNotice + `📊 <b>Action Selected: AI Recruiter Match Score (/score)</b>\n\n` +
                `✨ I will evaluate your fit with an instant 0–100 match score and 4-pillar breakdown.\n\n` +
                `📥 <b>Next Step:</b>\n` +
                `Please send your <b>Job Description</b> (or title, company, requirements/link) in your next message!\n\n` +
