      }
      commandAction = 'SCORE';
      jdText = rest;
    } else if (firstWord === '/recruiters' || firstWord === '/recruiter' || firstWord === '/contacts' || firstWord === '/hr') {
      if (!rest || rest.length < 2) {
        setTelegramState(chatId, { action: 'RECRUITERS' });
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
