                `✨ I will find recruiters, hiring managers, and direct 1-tap Google X-Ray search links for any employer.\n\n` +
                `📥 <b>Next Step:</b>\n` +
                `Please send the <b>Company Name</b> (e.g. <code>Shopify</code> or <code>RBC Toronto</code>) in your next message!\n\n` +
                `<i>(Send <code>/cancel</code> anytime to abort)</i>`
            },
            json: true
          });
        }
        continue;
      }
      commandAction = 'RECRUITERS';
      jdText = rest;
    } else if (firstWord === '/apply' || firstWord === '/application') {
      if (!rest || (rest.length < 15 && !rest.includes('http://') && !rest.includes('https://'))) {
        setTelegramState(chatId, { action: 'APPLY' });
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: abortNotice + `📝 <b>Action Selected: Complete Application Package (/apply)</b>\n\n` +
                `✨ I will generate <b>BOTH</b> a tailored ATS-compliant PDF resume and an aligned cover letter.\n\n` +
                `📥 <b>Next Step:</b>\n` +
                `Please send your <b>Job Description</b> (or title, company, requirements/link) in your next message!\n\n` +
