    } else if (firstWord === '/resume' || firstWord === '/tailor-resume' || firstWord === '/cv') {
      if (!rest || (rest.length < 15 && !rest.includes('http://') && !rest.includes('https://'))) {
        setTelegramState(chatId, { action: 'RESUME' });
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
