    } else if (firstWord === '/coverletter' || firstWord === '/cover-letter' || firstWord === '/cl') {
      if (!rest || (rest.length < 15 && !rest.includes('http://') && !rest.includes('https://'))) {
        setTelegramState(chatId, { action: 'COVERLETTER' });
        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: abortNotice + `✉️ <b>Action Selected: Tailored Cover Letter (/coverletter)</b>\n\n` +
                `✨ I will draft a targeted cover letter aligned to the job requirements directly in chat.\n\n` +
                `📥 <b>Next Step:</b>\n` +
                `Please send your <b>Job Description</b> in your next message!\n\n` +
                `<i>💡 Example:</i>\n` +
                `<code>Business Intelligence Analyst at Canadian Tire\nRequirements: Power BI, DAX, Retail KPI reporting...</code>\n\n` +
                `<i>(Send <code>/cancel</code> anytime to abort)</i>`
            },
            json: true
          });
        }
        continue;
      }
      commandAction = 'COVERLETTER';
      jdText = rest;
    } else if (!isCommand) {
      // 2e. NON-COMMAND MESSAGE: Check if user has a pending action!
      const userState = getTelegramState(chatId);

      // Conversational Step 1: AWAIT_LOCATION_CHOICE (User types custom location or option number)
      if (userState && userState.action === 'AWAIT_LOCATION_CHOICE') {
        let chosenLocs = [];
        let nearestNote = '';
        const numIdx = parseInt(text.trim());
        if (!isNaN(numIdx) && numIdx >= 1 && userState.locationOptions && userState.locationOptions[numIdx - 1]) {
          chosenLocs = [userState.locationOptions[numIdx - 1]];
        } else {
          // Custom location entered: dynamically expand with nearest metropolitan hubs from geo-hierarchy.json
          const expansion = geoHelper ? geoHelper.expandCustomLocationsWithGeo(text) : { locations: parseSmartLocations(text), note: '' };
          chosenLocs = expansion.locations;
          if (expansion.note) nearestNote = '\n' + expansion.note;
        }

        const stagedProfile = userState.stagedProfile || {};
        stagedProfile.locations = chosenLocs;

        setTelegramState(chatId, {
          action: 'AWAIT_WORK_TYPE_CHOICE',
          stagedProfile: stagedProfile,
          locationOptions: userState.locationOptions,
          primaryRole: userState.primaryRole || 'Target Role',
          seniorityRole: userState.seniorityRole || userState.primaryRole || 'Target Role',
          yearsOfExp: userState.yearsOfExp || 1,
          variationsStr: userState.variationsStr || 'Target Role; Senior Target Role'
        });

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `📍 <b>Locations Set:</b> ${stagedProfile.locations.join(', ')}${nearestNote}\n\n` +
                `<b>Step 2 of 3: Workplace Preference</b>\n` +
                `Select your preferred work arrangement:\n\n` +
                `• <b>Tap a button below</b>, OR\n` +
                `• <b>Type custom preference in chat</b> (e.g. <code>Remote or Hybrid</code>)`,
              reply_markup: {
                inline_keyboard: [
                  [
                    { text: '🌐 Remote Only', callback_data: 'ONBOARD_WORK:REMOTE' },
                    { text: '🏢 Hybrid & Remote', callback_data: 'ONBOARD_WORK:HYBRID' }
                  ],
                  [
                    { text: '📍 Onsite / Any', callback_data: 'ONBOARD_WORK:ONSITE' },
                    { text: '✨ Open to All', callback_data: 'ONBOARD_WORK:ALL' }
                  ]
                ]
              }
            },
            json: true
          });
        }
        continue;
      }

      // Conversational Step 2: AWAIT_WORK_TYPE_CHOICE (User types custom workplace mode)
      if (userState && userState.action === 'AWAIT_WORK_TYPE_CHOICE') {
        const trimmed = text.trim();
        const stagedProfile = userState.stagedProfile || {};
        const detectedCity = (userState.locationOptions && userState.locationOptions[0]) || null;
        const harmonized = harmonizeLocationAndWorkType(stagedProfile.locations, trimmed, detectedCity);
        stagedProfile.locations = harmonized.locations;
        stagedProfile.work_type = harmonized.work_type;

        setTelegramState(chatId, {
          action: 'AWAIT_ROLE_CHOICE',
          stagedProfile: stagedProfile,
          locationOptions: userState.locationOptions,
          primaryRole: userState.primaryRole || 'Target Role',
          seniorityRole: userState.seniorityRole || userState.primaryRole || 'Target Role',
          yearsOfExp: userState.yearsOfExp || 1,
          variationsStr: userState.variationsStr || 'Target Role; Senior Target Role'
        });

        const noteText = harmonized.harmonizationNote ? ('\n<i>' + harmonized.harmonizationNote + '</i>') : '';
        const expLabel = (userState.yearsOfExp && userState.yearsOfExp > 0) ? (' (' + userState.yearsOfExp + '+ yrs exp)') : '';

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `🏢 <b>Workplace Mode:</b> ${harmonized.work_type}${noteText}\n` +
                `📍 <b>Locations:</b> ${harmonized.locations.join(', ')}\n\n` +
                `<b>Step 3 of 3: Target Job Titles</b>\n\n` +
                `Suggested roles based on your verified career history${expLabel}:\n` +
                `1️⃣ <b>${userState.primaryRole || 'Target Role'}</b> <i>(Primary role)</i>\n` +
                `2️⃣ <b>${userState.seniorityRole || userState.primaryRole || 'Target Role'}</b> <i>(Experience-aligned)</i>\n` +
                `3️⃣ <b>${userState.variationsStr || 'Target Role'}</b> <i>(Domain & skill variations)</i>\n\n` +
                `• <b>Tap a button below</b>, OR\n` +
                `• <b>Type custom titles in chat</b> separated by semicolons (e.g. <code>Data Analyst; BI Analyst</code>)`,
              reply_markup: {
                inline_keyboard: [
                  [{ text: `🎯 ${userState.primaryRole || 'Target Role'} (Primary)`, callback_data: 'ONBOARD_ROLE:PRIMARY' }],
                  [{ text: `🚀 ${userState.seniorityRole || userState.primaryRole || 'Target Role'} (Exp-Aligned)`, callback_data: 'ONBOARD_ROLE:SENIORITY' }],
                  [{ text: '💡 All Suggested Variations', callback_data: 'ONBOARD_ROLE:VARIATIONS' }],
