                ]
              }
            },
            json: true
          });
        }
        continue;
      }

      // Conversational Step 3: AWAIT_ROLE_CHOICE (User types custom titles or option number)
      if (userState && userState.action === 'AWAIT_ROLE_CHOICE') {
        const trimmed = text.trim();
        const primaryRole = userState.primaryRole || 'Target Role';
        const seniorityRole = userState.seniorityRole || primaryRole;
        let chosenTitles = [];

        if (trimmed === '1') {
          chosenTitles = [primaryRole];
        } else if (trimmed === '2') {
          chosenTitles = [seniorityRole];
        } else if (trimmed === '3') {
          chosenTitles = (userState.variationsStr || primaryRole).split(';').map(s => s.trim()).filter(Boolean);
        } else {
          chosenTitles = trimmed.split(/[;,]/).map(s => {
            const clean = s.trim();
            return clean.replace(/\b\w+/g, w => /^(and|or|of|in|for|at|the|to)$/i.test(w) ? w.toLowerCase() : w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
          }).filter(Boolean);
        }

        const stagedProfile = userState.stagedProfile || {};
        stagedProfile.target_titles = chosenTitles.length > 0 ? chosenTitles : [primaryRole];

        // Save finalized profile
        const dataDir = fs.existsSync('/data') ? '/data' : 'data';
        try {
          fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.json'), JSON.stringify(stagedProfile, null, 2), 'utf8');
          fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'profiles', 'master-profile.backup.json'), JSON.stringify(stagedProfile, null, 2), 'utf8');
        } catch(e) {}

        setTelegramState(chatId, null); // Clear state

        const totalBullets = (stagedProfile.experience || []).reduce((acc, exp) => acc + (exp.bullets ? exp.bullets.length : 0), 0);
        const skillsList = Array.isArray(stagedProfile.skills) ? stagedProfile.skills : [];

        if (chatId && botToken) {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
            body: {
              chat_id: chatId,
              parse_mode: 'HTML',
              text: `🎉 <b>MASTER PROFILE CONFIGURED & ACTIVATED!</b>\n\n` +
                `👤 <b>Candidate:</b> ${stagedProfile.name || 'Candidate'}\n` +
                `🎯 <b>Target Roles:</b> ${stagedProfile.target_titles.join(', ')}\n` +
