                `💼 <b>Verified Experience:</b> ${(stagedProfile.experience || []).length} Roles (${totalBullets} achievements preserved verbatim)\n` +
                `🛠️ <b>Verified Skills:</b> ${skillsList.length} skills indexed\n\n` +
                `💾 <b>Saved to:</b> <code>data/profiles/master-profile.json</code> <i>(Zero fabrication verified)</i>\n\n` +
                `🚀 <b>Ready for Action!</b> Next, try sending:\n` +
                `• <code>/find-jobs</code> — Run instant multi-board job scan right now\n` +
                `• <code>/apply</code> — Generate tailored PDF Resume + Cover Letter\n` +
                `• <code>/resume</code> — Generate tailored PDF Resume only\n` +
                `• <code>/score</code> — Instant 0–100 AI Recruiter Fit Score`
            },
            json: true
          });
        }
        continue;
      }

      // Conversational Step: AWAIT_PROFILE_JSON (User pasted updated JSON)
      if (userState && userState.action === 'AWAIT_PROFILE_JSON') {
        let valResult = null;
        if (profileValidator && typeof profileValidator.validateProfileJson === 'function') {
