        } else {
          try {
            const clean = text.replace(/^\x60{3}(?:json)?\s*/i, '').replace(/\s*\x60{3}$/i, '').trim();
            const parsed = JSON.parse(clean);
            const errs = [];
            if (!parsed.name) errs.push('Missing required field "name"');
            if (!parsed.skills || !Array.isArray(parsed.skills)) errs.push('Missing required field "skills" array');
            if (!parsed.experience || !Array.isArray(parsed.experience)) errs.push('Missing required field "experience" array');
            if (errs.length > 0) valResult = { valid: false, errors: errs };
            else valResult = { valid: true, profile: parsed };
          } catch(e) {
            valResult = { valid: false, errors: ['JSON Syntax Error: ' + e.message] };
