    }

    if (!commandAction || !jdText) continue;

    // 2e2. EXECUTE RECRUITERS LOOKUP COMMAND
    if (commandAction === 'RECRUITERS') {
      const companyClean = jdText.replace(/^(company|employer|at|for):?\s*/i, '').trim();
      const cityClean = (masterProfile.locations && masterProfile.locations[0]) || '';
      if (chatId && botToken) {
        try {
          await this.helpers.httpRequest({
            method: 'POST',
            url: `https://api.telegram.org/bot${botToken}/sendMessage`,
