          breakdown: { title_fit_score: 85, skills_fit_score: 80, seniority_fit_score: 85, domain_fit_score: 80 },
          should_apply: matched.length >= 3,
          company_tier: 'Enterprise / Product',
          priority_level: matched.length >= 4 ? 'High' : 'Medium',
          key_matched_skills: matched.slice(0, 6),
          missing_skills: [],
          why_this_fits: 'Good keyword overlap with your profile.'
