      const score = evalData.overall_score || 70;
      const verdict = evalData.should_apply ? '✅ <b>HIGH RECOMMENDATION: APPLY</b>' : '⚠️ <b>POTENTIAL MISMATCH: PROCEED WITH CAUTION</b>';

      if (chatId && botToken) {
        const scoreMsg = `📊 <b>AI RECRUITER EVALUATION</b>\n\n` +
          `🎯 <b>Role:</b> ${jobData.title} @ ${jobData.company}\n` +
          `⭐ <b>Match Score: ${score}/100</b>\n` +
          `${verdict}\n\n` +
          `<b>Pillar Breakdown:</b>\n` +
          `• Title Fit: ${evalData.breakdown?.title_fit_score ?? 80}%\n` +
          `• Skills Overlap: ${evalData.breakdown?.skills_fit_score ?? 80}%\n` +
